import { readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const figuresDir = join(process.cwd(), 'public/figures');
const files = readdirSync(figuresDir)
  .filter((name) => /\.(webp|png|jpe?g)$/i.test(name))
  .sort();

const body = [
  '/* Generated by scripts/generate-bundled-figures.mjs. Do not edit by hand. */',
  "import type { ImageSourcePropType } from 'react-native';",
  '',
  'export const BUNDLED_FIGURES: Record<string, ImageSourcePropType> = {',
  ...files.map((name) => `  '/figures/${name}': require('../../public/figures/${name}'),`),
  '};',
  '',
].join('\n');

writeFileSync(join(process.cwd(), 'lib/figures/bundledAssets.ts'), body);
console.log(`Wrote ${files.length} bundled figures.`);
